pub fn caesar(s: &str, shift: u8) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if c.is_ascii_lowercase() {
            out.push(c.to_ascii_lowercase().next().map(|n| (n + shift - 97) % 26 + 97).unwrap());
        } else if c.is_ascii_uppercase() {
            out.push(c.to_ascii_uppercase().next().map(|n| (n + shift - 65) % 26 + 65).unwrap());
        } else {
            out.push(c);
        }
    }
    out
}

