pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    if k == 0 || v.is_empty() {
        return v.to_vec();
    }

    let len = v.len();
    let k = k % len;

    let mut out = vec![0; len];
    for i in 0..len {
        out[(i + k) % len] = v[i];
    }
    out
}

